create table capa (id varchar(255) primary key, ai_system_id varchar(255) not null references ai_system(id), signal_id varchar(255) not null references monitoring_signal(id), risk varchar(4000) not null, mitigation varchar(4000) not null, owner varchar(255) not null, due_at varchar(255) not null, status varchar(255) not null, effectiveness_evidence varchar(4000), closed_at varchar(255));
